// Socket Event Payload Types (from contracts/socket.json)
export interface AuctionBidUpdatedPayload {
  auctionId: string;
  bidId?: string;
  bidderId: string;
  amount: string;
  version: number;
  placedAt?: string;
  createdAt?: string;
  [key: string]: unknown;
}

export interface AuctionStatusChangedPayload {
  auctionId: string;
  status: 'ACTIVE' | 'ENDED';
  version: number;
  winnerId?: string | null;
  finalPrice?: string | null;
  startedAt?: string;
  endedAt?: string;
  [key: string]: unknown;
}

export interface AuctionSubscribeAck {
  ok: boolean;
  auctionId?: string;
  code?: string;
}
